struct Aggregate:Count{Long64_t events=0;double n2=0,k2=0,nk=0,u2=0,nu=0;void cluster(Long64_t n,Long64_t k,Long64_t u){if(!n)return;++events;n2+=double(n)*n;k2+=double(k)*k;nk+=double(n)*k;u2+=double(u)*u;nu+=double(n)*u;}};
